{"content":"import { createFileRoute, useNavigate } from "@tanstack/react-router";
import { useEffect, useState, type FormEvent } from "react";
import { toast } from "sonner";
import { supabase } from "@/integrations/supabase/client";
import { lovable } from "@/integrations/lovable/index";

export const Route = createFileRoute("/auth")({
  head: () => ({
    meta: [
      { title: "Staff & Customer Sign In | Pickrel Brothers Inc." },
      {
        name: "description",
        content:
          "Sign in to your Pickrel Brothers account for contract pricing, saved quotes and order history, or access the staff pricing console.",
      },
      { property: "og:title", content: "Sign In | Pickrel Brothers Inc." },
      {
        property: "og:description",
        content: "Account pricing, quotes and the Pickrel Brothers staff pricing console.",
      },
      { name: "robots", content: "noindex" },
    ],
  }),
  validateSearch: (search: Record<string, unknown>): { admin?: boolean } =>
    search['admin'] === true || search['admin'] === "true" ? { admin: true } : {},
  component: AuthPage,
});

/** Admins land in the console; everyone else goes to the customer account page. */
async function destinationForCurrentUser(): Promise<"/admin" | "/account"> {
  const { data: userData } = await supabase.auth.getUser();
  const user = userData.user;
  if (!user) return "/account";
  const { data } = await supabase
    .from("user_roles")
    .select("role, expires_at")
    .eq("user_id", user.id)
    .eq("role", "admin");
  const now = Date.now();
  const active = (data ?? []).some(
    (r) => !r.expires_at || new Date(r.expires_at).getTime() > now,
  );
  return active ? "/admin" : "/account";
}

function AuthPage() {
  const navigate = useNavigate();
  const { admin: adminMode } = Route.useSearch();
  const [mode, setMode] = useState<"signin" | "signup">("signin");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    void supabase.auth.getSession().then(async ({ data }) => {
      if (data.session) void navigate({ to: await destinationForCurrentUser() });
    });
  }, [navigate]);

  async function onSubmit(e: FormEvent) {
    e.preventDefault();
    setBusy(true);
    try {
      if (mode === "signin") {
        const { error } = await supabase.auth.signInWithPassword({ email, password });
        if (error) throw error;
        const dest = await destinationForCurrentUser();
        if (adminMode && dest !== "/admin") {
          await supabase.auth.signOut();
          toast.error("This account does not have admin access.");
          return;
        }
        toast.success("Signed in");
        void navigate({ to: dest });
      } else {
        const { error } = await supabase.auth.signUp({
          email,
          password,
          options: { emailRedirectTo: `${window.location.origin}/account` },
        });
        if (error) throw error;
        toast.success("Account created — check your email if confirmation is required.");
      }
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Sign in failed");
    } finally {
      setBusy(false);
    }
  }

  async function onMagicLink() {
    if (!email) {
      toast.error("Enter your email first");
      return;
    }
    setBusy(true);
    try {
      const { error } = await supabase.auth.signInWithOtp({
        email,
        options: { emailRedirectTo: `${window.location.origin}/account` },
      });
      if (error) throw error;
      toast.success("Login link sent — check your email.");
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Could not send login link");
    } finally {
      setBusy(false);
    }
  }

  async function onForgotPassword() {
    if (!email) {
      toast.error("Enter your email first");
      return;
    }
    setBusy(true);
    try {
      const { error } = await supabase.auth.resetPasswordForEmail(email, {
        redirectTo: `${window.location.origin}/reset-password`,
      });
      if (error) throw error;
      toast.success("Password reset email sent.");
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Could not send reset email");
    } finally {
      setBusy(false);
    }
  }

  async function onGoogle() {
    const result = await lovable.auth.signInWithOAuth("google", {
      redirect_uri: window.location.origin,
    });
    if (result.error) {
      toast.error("Google sign-in failed");
      return;
    }
    if (result.redirected) return;
    void navigate({ to: await destinationForCurrentUser() });
  }


  return (
    <div className="container-page py-16">
      <div className="mx-auto max-w-md rounded-md border border-border bg-card p-8 shadow-card">
        <h1 className="font-display text-3xl font-bold uppercase text-navy">
          {mode === "signin" ? "Sign in" : "Create account"}
        </h1>
        <p className="mt-2 text-sm text-muted-foreground">
          Account customers see their contract pricing. Pickrel Brothers staff reach the pricing
          console from here.
        </p>

        <form onSubmit={onSubmit} className="mt-6 space-y-4">
          <label className="block text-sm font-semibold text-navy">
            Email
            <input
              type="email"
              required
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="mt-1 block w-full rounded-md border border-input bg-card px-3 py-2 text-sm text-foreground"
            />
          </label>
          <label className="block text-sm font-semibold text-navy">
            Password
            <input
              type="password"
              required
              minLength={6}
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="mt-1 block w-full rounded-md border border-input bg-card px-3 py-2 text-sm text-foreground"
            />
          </label>
          <button
            type="submit"
            disabled={busy}
            className="w-full rounded-md bg-navy px-6 py-3 font-display font-bold uppercase tracking-wide text-navy-foreground hover:bg-navy-muted disabled:opacity-60"
          >
            {mode === "signin" ? "Sign in" : "Create account"}
          </button>
        </form>

        <button
          type="button"
          onClick={onMagicLink}
          disabled={busy}
          className="mt-3 w-full rounded-md border border-input px-6 py-2.5 text-sm font-semibold text-navy hover:bg-secondary disabled:opacity-60"
        >
          Email me a one-time login link
        </button>

        <button
          type="button"
          onClick={onForgotPassword}
          disabled={busy}
          className="mt-2 w-full text-sm font-semibold text-sky hover:underline disabled:opacity-60"
        >
          Forgot password? Send reset email
        </button>

        <button
          type="button"
          onClick={onGoogle}
          className="mt-3 w-full rounded-md border border-input px-6 py-2.5 text-sm font-semibold text-navy hover:bg-secondary"
        >
          Continue with Google
        </button>


        <button
          type="button"
          onClick={() => setMode(mode === "signin" ? "signup" : "signin")}
          className="mt-4 w-full text-sm font-semibold text-sky hover:underline"
        >
          {mode === "signin" ? "Need an account? Sign up" : "Already registered? Sign in"}
        </button>
      </div>
    </div>
  );
}
